VALUES ('apple-ipad-10th-gen', 'Apple iPad 10th Gen — 64GB, WiFi', 'tablets', 620000, 620000, 508000, 10, 0.5, '/assets/products/apple-ipad-10th-gen.webp', 'The iPad 10th Gen is the gateway to Apple''s tablet ecosystem. Featuring the A14 Bionic chip, a vibrant 10.9-inch Liquid Retina display, and an all-screen design with four bold colors, this iPad handles everyday tasks, creative apps, and games with remarkable fluidity. The USB-C connector enables universal accessory compatibility, while the 12MP Ultra Wide front camera with Center Stage keeps you perfectly framed during video calls. With all-day battery life and iPadOS multitasking, this is the perfect first iPad for students, families, and casual creators. Condition: Brand new, sealed, original Apple packaging, 1-year Apple warranty.', 1, 1718400000, 1, 508000, '/assets/products/apple-ipad-10th-gen.webp', 564000, 4.5, 1, 'Apple', 0, 1, 'gadgets');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('samsung-galaxy-tab-s9-ultra', 'Samsung Galaxy Tab S9 Ultra — 14.6", 256GB, 12GB RAM, WiFi', 'tablets', 1450000, 1450000, 1189000, 10, 0.5, '/assets/products/samsung-galaxy-tab-s9-ultra.webp', 'The Samsung Galaxy Tab S9 Ultra is the largest and most advanced Android tablet ever created. The colossal 14.6-inch Dynamic AMOLED 2X display with 120Hz adaptive refresh rate, HDR10+, and 1848x2960 resolution delivers a cinematic canvas that rivals laptop screens. The Snapdragon 8 Gen 2 for Galaxy processor, 12GB RAM, and 256GB storage with microSD expansion handle desktop-class multitasking. The included S Pen with 2.8ms latency, IP68 water resistance, and DeX mode that transforms the tablet into a desktop experience make this the ultimate Android productivity and entertainment device. Condition: Brand new, sealed, original Samsung packaging, 1-year Samsung warranty.', 1, 1718400000, 1, 1189000, '/assets/products/samsung-galaxy-tab-s9-ultra.webp', 1319000, 4.5, 1, 'Samsung', 0, 1, 'gadgets');

