INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('breville-juice-fountain-cold-xl', 'Breville Juice Fountain Cold XL — Brushed Stainless', 'kitchen', 285000, 285000, 233000, 10, 5.0, '/assets/products/breville-juice-fountain-cold-xl.webp', 'The Breville Juice Fountain Cold XL delivers nutrient-rich juice with minimal oxidation. The 3.5-inch extra-wide chute accepts whole apples and oranges without pre-cutting, while the Cold Spin Technology extracts juice and transfers it up through a precision mesh filter, keeping temperature rise below 1.8°F to preserve enzymes and vitamins. The 1200-watt motor and Italian-made precision mesh filter ensure maximum juice yield and silky smooth texture, while the Noise Reduction Technology reduces mechanical noise by 40%. With a 70 fl oz seal and store jug, custom juice nozzle for direct-to-glass pouring, and dishwasher-safe components, this juicer makes daily wellness effortless. Condition: Brand new, sealed, original Breville packaging, 2-year Breville warranty.', 1, 1718400000, 1, 233000, '/assets/products/breville-juice-fountain-cold-xl.webp', 259000, 4.5, 0, 'Breville', 0, 1, 'gadgets');

