VALUES ('delonghi-la-specialista-arte', 'De''Longhi La Specialista Arte — Manual Espresso Machine, Black', 'kitchen', 485000, 485000, 397000, 10, 5.0, '/assets/products/delonghi-la-specialista-arte.webp', 'The De''Longhi La Specialista Arte bridges the gap between manual craft and assisted precision. The integrated conical burr grinder with 8 settings delivers freshly ground coffee directly into the portafilter, while the My LatteArt steam wand creates silky microfoam for latte art. The three pre-set recipes — Espresso, Americano, and Hot Water — provide one-touch convenience, while the professional 15-bar pump and active temperature control with three infusion levels ensure optimal extraction. The compact, stylish design with metal finishes brings café aesthetics to your countertop, and the dishwasher-safe parts simplify maintenance. For coffee enthusiasts who want hands-on control without the steep learning curve. Condition: Brand new, sealed, original De''Longhi packaging, 2-year De''Longhi warranty.', 1, 1718400000, 1, 397000, '/assets/products/delonghi-la-specialista-arte.webp', 441000, 4.5, 0, 'De''Longhi', 0, 1, 'gadgets');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('withings-body-scan', 'Withings Body Scan — WiFi Smart Scale with Segmental Body Composition', 'health', 285000, 285000, 233000, 10, 1.0, '/assets/products/withings-body-scan.webp', 'The Withings Body Scan is the most advanced smart scale ever created for home use. Beyond weight, this revolutionary device provides segmental body composition analysis — measuring fat and muscle mass in each arm, each leg, and your torso independently via multi-frequency Bioelectrical Impedance Analysis. The integrated handle contains sensors for a 6-lead ECG that detects atrial fibrillation, and an electrochemical sensor that assesses nerve activity in your feet. The 3.2-inch color display shows trends and weather, while WiFi sync pushes data to the Withings app and Apple Health. With automatic multi-user recognition and a 1-year rechargeable battery, this scale transforms your bathroom into a clinical health monitoring station. Condition: Brand new, sealed, original Withings packaging, 1-year Withings warranty.', 1, 1718400000, 1, 233000, '/assets/products/withings-body-scan.webp', 259000, 4.5, 0, 'Withings', 0, 1, 'gadgets');

