INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('baseus-adaman-65w', 'Baseus Adaman 65W — 20000mAh, 3-Port, Digital Display, Black', 'accessories', 38000, 38000, 31000, 10, 0.3, '/assets/products/baseus-adaman-65w.webp', 'The Baseus Adaman 65W is the power bank that charges your laptop and phone simultaneously at full speed. The 20000mAh capacity provides multiple charges for smartphones and a full charge for most USB-C laptops, while the 65W Power Delivery output via USB-C fuels MacBook Air and similar ultrabooks. The alloy metal body with digital LED display shows exact remaining percentage and charging voltage, and the multi-protection safety system guards against overcurrent, overheating, and short circuits. With two USB-A ports and one USB-C port, this power bank is the mobile office essential for remote workers and business travelers. Condition: Brand new, sealed, original Baseus packaging, 1-year Baseus warranty.', 1, 1718400000, 1, 31000, '/assets/products/baseus-adaman-65w.webp', 34000, 4.5, 0, 'Baseus', 0, 1, 'gadgets');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
