VALUES ('ugreen-usb-c-to-lightning-cable', 'UGREEN USB-C to Lightning Cable — MFi Certified, 1M, Braided, Black', 'accessories', 9500, 9500, 7000, 10, 0.3, '/assets/products/ugreen-usb-c-to-lightning-cable.webp', 'The UGREEN USB-C to Lightning Cable is the MFi-certified lifeline that fast-charges your iPhone. Supporting Apple''s 20W PD fast charging, this cable charges iPhone 8 and later from 0 to 50% in just 30 minutes when paired with a USB-C PD charger. The nylon braided construction with aluminum housings withstands daily abuse, while the C94 Apple original connector chip ensures perfect compatibility without the "Accessory Not Supported" error. With 480Mbps data sync for iTunes and iCloud backups, this is the cable that every iPhone user needs in their bag, car, and bedside table. Condition: Brand new, sealed, original UGREEN packaging, 1-year UGREEN warranty.', 1, 1718400000, 1, 7000, '/assets/products/ugreen-usb-c-to-lightning-cable.webp', 8000, 4.5, 0, 'UGREEN', 0, 1, 'gadgets');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
