INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('godox-sl-60w', 'Godox SL-60W — 60W LED Video Light, Bowens Mount, Remote Control', 'cameras', 85000, 85000, 69000, 10, 1.0, '/assets/products/godox-sl-60w.webp', 'The Godox SL-60W is the LED video light that has become the YouTube studio standard. The 60W COB LED delivers the equivalent brightness of a 600W tungsten bulb while running cool and consuming minimal electricity — essential for Nigerian creators managing generator costs. The Bowens mount compatibility provides access to a vast ecosystem of softboxes, beauty dishes, and reflectors, while the remote control adjusts brightness from 10% to 100% without touching the light. The 5600K daylight-balanced color temperature with CRI 95+ ensures accurate skin tones, and the quiet fan cooling prevents audio interference during recording. For aspiring YouTubers, product photographers, and interview setups seeking professional lighting on a budget. Condition: Brand new, sealed, original Godox packaging, 1-year Godox warranty.', 1, 1718400000, 1, 69000, '/assets/products/godox-sl-60w.webp', 77000, 4.5, 0, 'Godox', 0, 1, 'gadgets');

