VALUES ('nextbase-622gw-1', 'Nextbase 622GW — 4K Dash Cam, Alexa Built-in, Emergency SOS, Black', 'car-tech', 85000, 85000, 69000, 10, 0.3, '/assets/products/nextbase-622gw-1.webp', 'The Nextbase 622GW is the 4K dash cam with features that could save your life. The 4K resolution at 30fps captures license plates and road details with stunning clarity, while the what3words integration provides precise location data to emergency services. The Alexa Built-in enables voice-controlled navigation, music, and smart home control from your car, and the Emergency SOS automatically alerts first responders with your location after a serious crash. The intelligent parking mode with time-lapse recording monitors your vehicle 24/7, and the polarizing filter reduces windshield glare. For safety-focused drivers who want the most advanced dash cam with life-saving emergency features. Condition: Brand new, sealed, original Nextbase packaging, 1-year Nextbase warranty.', 1, 1718400000, 1, 69000, '/assets/products/nextbase-622gw-1.webp', 77000, 4.5, 0, 'Nextbase', 0, 1, 'gadgets');

INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
