INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('furman-pst-8d', 'Furman PST-8D — Power Station, SMP, LiFT, EVS, 15A, Black', 'gadgets', 32000, 32000, 26000, 10, 1.0, '/assets/products/furman-pst-8d.webp', 'The Furman PST-8D is the studio power conditioner that protects and improves audio quality. The Series Multi-Stage Protection absorbs surges without sacrificing themselves, while the Linear Filtering Technology reduces AC line noise and hum that degrades audio. The Extreme Voltage Shutdown protects equipment from sustained over-voltage, and the isolated outlet banks prevent digital noise from contaminating analog gear. The 15A capacity with circuit breaker handles complete studio setups, and the pull-out light illuminates rack connections in dark spaces. For musicians, producers, and home theater enthusiasts who want professional power conditioning that improves sound quality while protecting expensive equipment. Condition: Brand new, sealed, original Furman packaging, 5-year Furman warranty.', 1, 1718400000, 1, 26000, '/assets/products/furman-pst-8d.webp', 29000, 4.5, 0, 'Generic', 0, 1, 'gadgets');

