INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('kef-ls50-wireless-ii', 'KEF LS50 Wireless II — Active Speakers, Uni-Q, MAT, AirPlay 2, Mineral White', 'gadgets', 985000, 985000, 807000, 10, 1.0, '/assets/products/kef-ls50-wireless-ii.webp', 'The KEF LS50 Wireless II is the active speaker system that redefines wireless HiFi. The Uni-Q driver with Metamaterial Absorption Technology eliminates 99% of rear driver distortion for purer sound, while the 380W per speaker with dedicated amplifiers for each driver delivers effortless dynamics. The wireless streaming supports AirPlay 2, Chromecast, Roon Ready, and MQA decoding, and the HDMI eARC connects directly to TVs. The KEF Connect app provides room EQ and source management, and the compact design with stunning finish options suits any interior. For audiophiles who want reference-grade sound with wireless streaming and TV integration in a beautiful, compact package. Condition: Brand new, sealed, original KEF packaging, 2-year KEF warranty.', 1, 1718400000, 1, 807000, '/assets/products/kef-ls50-wireless-ii.webp', 896000, 4.5, 1, 'Generic', 0, 1, 'gadgets');

